<?php
namespace App\Http\Controllers\Storefront\Commerce;
use App\Http\Controllers\Controller; use App\Http\Requests\Storefront\Commerce\CheckoutRequest; use App\Models\{Address,Cart,Order}; use App\Services\Orders\OrderService; use Illuminate\Http\RedirectResponse; use Inertia\{Inertia,Response};
class OrderController extends Controller { public function create():Response{$currentCart=app(\App\Actions\Cart\GetCurrentCart::class)->handle(request()->user(),request()->session()->getId());if(!$currentCart||$currentCart->items->isEmpty()){return redirect()->route('cart.show')->with('error','Your cart is empty.');}$addresses=request()->user()->addresses()->get();return Inertia::render('Checkout/Create',['cart'=>$currentCart->load('items.product','items.variant'),'addresses'=>$addresses,'defaultCurrency'=>'USD']);} public function index():Response{return Inertia::render('Orders/Index',['orders'=>request()->user()->orders()->latest()->paginate()]);} public function show(Order $order):Response{$this->authorize('view',$order);return Inertia::render('Orders/Show',['order'=>$order->load('items')]);} public function store(CheckoutRequest $request,OrderService $service):RedirectResponse{$data=$request->validated();$order=$service->createFromCart($request->user(),Cart::findOrFail($data['cart_id']),Address::findOrFail($data['billing_address_id']),Address::findOrFail($data['shipping_address_id']),$data['currency']);return to_route('orders.show',$order)->with('success','Order created.');} }
